      font-size: 0.85rem;
      font-weight: 600;
    }
    .efficiency-badge svg { fill: none; stroke: #ffb3b3; }

    .donate-amounts {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 0.75rem;
    }
    .amount-btn {
      background: rgba(255,255,255,0.12);
      border: 1.5px solid rgba(255,255,255,0.25);
      border-radius: var(--radius);
      padding: 1rem;
      text-align: center;
      cursor: pointer;
      transition: all var(--transition);
      color: var(--white);
    }
    .amount-btn:hover, .amount-btn.selected {
      background: var(--white);
      border-color: var(--white);
      color: var(--red);
    }
    .amount-btn strong { display: block; font-size: 1.25rem; font-weight: 800; }
    .amount-btn span { font-size: 0.75rem; opacity: 0.8; }
    .amount-btn.selected span { opacity: 0.7; }

    .donate-submit { margin-top: 1rem; }
    .donate-submit .btn-white { width: 100%; justify-content: center; font-size: 1rem; padding: 0.9rem; }

    /* ── Footer ───────────────────────────────────────── */
    .site-footer {
      background: var(--navy-dark);
      color: rgba(255,255,255,0.75);
      padding: 4rem 0 2rem;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr 1fr;
      gap: 2.5rem;
      padding-bottom: 3rem;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .footer-brand .logo-mark { margin-bottom: 1rem; }
    .footer-brand .logo-text strong { color: #fff; }
    .footer-brand .logo-text span { color: rgba(255,255,255,0.5); }
    .footer-brand p {
      font-size: 0.85rem;
      line-height: 1.7;
      margin-top: 1rem;
      color: rgba(255,255,255,0.6);
      max-width: 260px;
    }
    .footer-socials {
      display: flex;
      gap: 0.5rem;
      margin-top: 1.25rem;
    }
    .social-link {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition);
    }
    .social-link:hover { background: var(--red); }
    .social-link svg { stroke: rgba(255,255,255,0.8); fill: none; }
    .footer-col h4 {
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--white);
      margin-bottom: 1rem;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }
    .footer-col ul a {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }
    .footer-col ul a:hover { color: var(--white); }

    .footer-bottom {
      padding-top: 2rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }
    .footer-bottom p { font-size: 0.78rem; color: rgba(255,255,255,0.45); }
    .footer-legal { display: flex; gap: 1.25rem; }
    .footer-legal a { font-size: 0.78rem; color: rgba(255,255,255,0.45); transition: color var(--transition); }
    .footer-legal a:hover { color: rgba(255,255,255,0.7); }

    /* ── Donate Modal ─────────────────────────────────── */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.55);
      backdrop-filter: blur(4px);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      opacity: 0;
      pointer-events: none;
      transition: opacity 300ms ease;
    }
    .modal-overlay.open {
      opacity: 1;
      pointer-events: all;
    }
    .modal {
      background: var(--white);
      border-radius: 1.25rem;
      width: 100%;
      max-width: 520px;
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: 0 25px 60px rgba(0,0,0,0.25);
      transform: translateY(20px) scale(0.97);
      transition: transform 300ms ease;
    }
    .modal-overlay.open .modal { transform: translateY(0) scale(1); }
    .modal-header {
      background: linear-gradient(135deg, var(--red) 0%, #9a1228 100%);
      padding: 2rem;
      border-radius: 1.25rem 1.25rem 0 0;
      position: relative;
    }
    .modal-header h2 { color: var(--white); font-size: 1.4rem; font-weight: 800; }
    .modal-header p { color: rgba(255,255,255,0.8); font-size: 0.875rem; margin-top: 0.25rem; }
    .modal-close {
      position: absolute;
      top: 1rem; right: 1rem;
      width: 32px; height: 32px;
      border-radius: 50%;
      background: rgba(255,255,255,0.2);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer;
      border: none;
      transition: background var(--transition);
    }
    .modal-close:hover { background: rgba(255,255,255,0.35); }
    .modal-close svg { stroke: #fff; fill: none; }
    .modal-body { padding: 2rem; }
    .modal-freq {
      display: flex;
      gap: 0.5rem;
      margin-bottom: 1.5rem;
      background: var(--gray-100);
      border-radius: var(--radius);
      padding: 0.25rem;
    }
    .freq-btn {
      flex: 1;
      padding: 0.5rem;
      border-radius: calc(var(--radius) - 2px);
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--gray-600);
      transition: all var(--transition);
      cursor: pointer;
      border: none;
      background: none;
    }
    .freq-btn.active { background: var(--white); color: var(--red); box-shadow: var(--shadow-sm); }
    .modal-amounts-label {
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      margin-bottom: 0.75rem;
    }
    .modal-amounts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.625rem;
      margin-bottom: 1rem;
    }
    .modal-amount-btn {
      border: 1.5px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 0.75rem 0.5rem;
      text-align: center;
      cursor: pointer;
      background: none;
      transition: all var(--transition);
    }
    .modal-amount-btn:hover { border-color: var(--red); color: var(--red); }
    .modal-amount-btn.selected { background: var(--red); border-color: var(--red); color: var(--white); }
    .modal-amount-btn strong { display: block; font-size: 1.1rem; font-weight: 800; }
    .modal-amount-btn span { font-size: 0.7rem; color: inherit; opacity: 0.75; }
    .modal-amount-btn.selected span { opacity: 0.85; }

    .modal-custom {
      position: relative;
      margin-bottom: 1.5rem;
    }
    .modal-custom label {
      display: block;
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--gray-600);
      margin-bottom: 0.4rem;
    }
    .modal-custom-input-wrap {
      position: relative;
    }
    .modal-custom-input-wrap .currency {
      position: absolute;
      left: 0.875rem;
      top: 50%;
      transform: translateY(-50%);
      color: var(--gray-400);
      font-weight: 700;
    }
    .modal-custom-input-wrap input {
      width: 100%;
      border: 1.5px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 0.75rem 0.75rem 0.75rem 1.75rem;
      font-size: 0.95rem;
      font-family: inherit;
      transition: border-color var(--transition);
      outline: none;
    }
    .modal-custom-input-wrap input:focus { border-color: var(--red); }

    .modal-impact {
      background: var(--red-light);
      border: 1px solid rgba(196,30,58,0.2);
      border-radius: var(--radius);
      padding: 0.875rem 1rem;
      display: flex;
      align-items: center;
      gap: 0.75rem;
      margin-bottom: 1.5rem;
    }
    .modal-impact svg { stroke: var(--red); fill: none; flex-shrink: 0; }
    .modal-impact p { font-size: 0.85rem; color: var(--red); font-weight: 500; line-height: 1.5; }

    .modal-donate-btn {
      width: 100%;
      background: var(--red);
      color: var(--white);
      border: none;
      border-radius: var(--radius);
      padding: 1rem;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: all var(--transition);
      letter-spacing: 0.02em;
    }
    .modal-donate-btn:hover { background: var(--red-dark); box-shadow: 0 4px 14px rgba(196,30,58,0.4); }
    .modal-secure {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.4rem;
      margin-top: 0.75rem;
      font-size: 0.75rem;
      color: var(--gray-400);
    }
    .modal-secure svg { stroke: var(--gray-400); fill: none; }

    /* ── Responsive ───────────────────────────────────── */
    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .involved-grid { grid-template-columns: repeat(2, 1fr); }
      .news-card { flex: 0 0 calc((100% - 1.5rem) / 2); }
    }

    @media (max-width: 768px) {
      .utility-bar .container { justify-content: center; }
      .main-nav { display: none; }
      .hamburger { display: flex; }
      .mission-grid { grid-template-columns: 1fr; }
      .mission-image { display: none; }
      .donate-cta-inner { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; text-align: center; }
      .involved-grid { grid-template-columns: 1fr; }
      .news-card { flex: 0 0 100%; }
      .hero-scroll { display: none; }
      .donate-amounts { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 480px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr; }
      .donate-cta-inner { gap: 2rem; }
      .modal-amounts-grid { grid-template-columns: repeat(2, 1fr); }
    }

    /* ── Scroll Animations ────────────────────────────── */
    .fade-in {
      opacity: 0;
      transform: translateY(24px);
      transition: opacity 500ms ease, transform 500ms ease;
    }
    .fade-in.visible {
      opacity: 1;
      transform: translateY(0);
    }
  </style>
</head>
<body>

